// trials_hd - per-function call counters for reverse engineering (diagnostic
// builds only, -DTRIALSHD_CALL_TRACE=ON). The wrappers that bump the counters
// are generated by tools/gen_trace_shims.py.

#pragma once

#include <atomic>
#include <cstddef>
#include <cstdint>

struct PPCContext;

namespace trials_hd::diag {

extern const size_t kTracedCount;
extern const uint32_t kTracedAddresses[];
extern std::atomic<uint64_t> g_call_counts[];
// Set for functions listed in TRIALS_HD_CALL_TRACE_ARGS; the shims then pass
// their context to CaptureArgs.
extern std::atomic<bool> g_capture_args[];

// Records r3-r8 and the return address of a call (a few samples per function
// per second) to the CSV named by TRIALS_HD_CALL_TRACE_ARGS_CSV.
void CaptureArgs(size_t index, const ::PPCContext& ctx);

// Starts a thread that appends one CSV row per function per second
// ("second,address,calls") to the file named by TRIALS_HD_CALL_TRACE_CSV.
// No-op when the variable is unset.
void StartCallTraceReporter();

}  // namespace trials_hd::diag
